; ==================================================================
; TILE PATTERN DATA
; File: patterns.asm
; Description: Tile pattern definitions for MSX Screen 2
; 12 tiles detected
; ==================================================================

PATTERN_DATA_BANK EQU ((tile_pattern_bank0 - #4000) / #2000)

; ==================================================================
; TILE PATTERN BANK 0 (Base patterns)
; ==================================================================
tile_pattern_bank0:
    ; Tile 0: left (8x8px = 1×1 chars = 1 MSX characters)
    db #3F, #7F, #E0, #C0, #C0, #E0, #7F, #3F
    ; Tile 1: bottom (8x8px = 1×1 chars = 1 MSX characters)
    db #C3, #C3, #C3, #C3, #C3, #E6, #7E, #3C
    ; Tile 2: right (8x8px = 1×1 chars = 1 MSX characters)
    db #FC, #FE, #07, #03, #03, #07, #FE, #F8
    ; Tile 3: top (8x8px = 1×1 chars = 1 MSX characters)
    db #3C, #7E, #E7, #C3, #C3, #C3, #C3, #C3
    ; Tile 4: vertical (8x8px = 1×1 chars = 1 MSX characters)
    db #C3, #C3, #C3, #C3, #C3, #C3, #C3, #C3
    ; Tile 5: horitz (8x8px = 1×1 chars = 1 MSX characters)
    db #FF, #FF, #00, #00, #00, #00, #FF, #FF
    ; Tile 6: corner_lt (8x8px = 1×1 chars = 1 MSX characters)
    db #3F, #7F, #E0, #C0, #C0, #C0, #C0, #C1
    ; Tile 7: corner_rt (8x8px = 1×1 chars = 1 MSX characters)
    db #FC, #FE, #07, #03, #03, #03, #03, #83
    ; Tile 8: corner_br (8x8px = 1×1 chars = 1 MSX characters)
    db #BD, #7E, #C3, #C3, #C3, #C3, #7E, #BD
    ; Tile 9: corner_bl (8x8px = 1×1 chars = 1 MSX characters)
    db #C1, #C0, #C0, #C0, #C0, #E0, #7F, #3F
    ; Tile 10: New Tile (8x8px = 1×1 chars = 1 MSX characters)
    db #83, #03, #03, #03, #03, #07, #FE, #FC
    ; Tile 11: dot (16x16px = 2×2 chars = 4 MSX characters)
    ; Character layout: 2×2 grid
    ; Row 0: Char0 Char1 
    ; Row 1: Char2 Char3 
    db #00, #00, #00, #00, #00, #00, #00, #01, #00, #00, #00, #00, #00, #00, #00, #80, #01, #00, #00, #00, #00, #00, #00, #00, #80, #00, #00, #00, #00, #00, #00, #00


; ==================================================================
; PATTERN LOADING FUNCTIONS
; ==================================================================
load_pattern_bank0:
    ; Load pattern bank 0 to VRAM (base patterns)
    ; Fast direct port access (no BIOS overhead)
    call mapper_push_p2
    ld a, PATTERN_DATA_BANK
    call mapper_set_bank_p2
    ld hl, tile_pattern_bank0
    ld de, CHRTBL2 + (128 * 8)    ; VRAM pattern table bank 0 (start at char 128)
    ld bc, 120    ; Total bytes for all tile characters (16x16 tiles = 4 chars each)
    call FAST_LDIRVM              ; Fast VRAM write (direct port access)
    call mapper_pop_p2
    ret

load_pattern_bank1:
    ; Load pattern bank 1: same patterns as bank 0 (MSX Screen 2 standard)
    ; Fast direct port access (no BIOS overhead)
    call mapper_push_p2
    ld a, PATTERN_DATA_BANK
    call mapper_set_bank_p2
    ld hl, tile_pattern_bank0     ; Same source as Bank 0
    ld de, CHRTBL2 + #800 + (128 * 8) ; VRAM pattern table bank 1 (+#800 offset + char 128)
    ld bc, 120    ; Total bytes for all tile characters
    call FAST_LDIRVM              ; Fast VRAM write (direct port access)
    call mapper_pop_p2
    ret

load_pattern_bank2:
    ; Load pattern bank 2: same patterns as bank 0 (MSX Screen 2 standard)
    ; Fast direct port access (no BIOS overhead)
    call mapper_push_p2
    ld a, PATTERN_DATA_BANK
    call mapper_set_bank_p2
    ld hl, tile_pattern_bank0     ; Same source as Bank 0
    ld de, CHRTBL2 + #1000 + (128 * 8) ; VRAM pattern table bank 2 (+#1000 offset + char 128)
    ld bc, 120    ; Total bytes for all tile characters
    call FAST_LDIRVM              ; Fast VRAM write (direct port access)
    call mapper_pop_p2
    ret

load_patterns_to_vram:
    ; Load all pattern banks to VRAM (required for SCREEN 2)
    ; This loads the same patterns to all 3 banks (standard MSX Screen 2 setup)
    call load_pattern_bank0
    call load_pattern_bank1
    call load_pattern_bank2
    ret

; ==================================================================
; END OF PATTERN DATA
; ==================================================================


