    db #00 ; Entity 1 (pacman_spr_right)
    db #00 ; Entity 2 (pacman_spr_right)
    ds 29, #FF ; Padding
 
; Table: Hardware Sprite Layer Colors 
; Format: db color_index 
sprite_layer_colors: 
    ; Entity 0 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 1 (pacman_spr_right) layers:
    db 10 ; Layer 0
    ; Entity 2 (pacman_spr_right) layers:
    db 10 ; Layer 0
    ds 29, 0 ; Padding

; ==================================================================
; SPRITE INITIALIZATION FUNCTIONS
; ==================================================================

init_sprites:
    call clear_all_sprites
    call load_sprite_patterns
    xor a
    ld (active_sprite_count), a
    ret

load_sprite_patterns:
    ; Load patterns for all active entities
    call mapper_push_p2
    ; Entity 0: PLACEHOLDER (1 layers)
    ; Base HW Sprite: 0
    ld a, SPRITE_PLACEHOLDER_PATTERN_BANK
    call mapper_set_bank_p2
    ld hl, SPRITE_PLACEHOLDER_PATTERN
    ld de, SPRPAT + (0 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 1: pacman_spr_right (1 layers)
    ; Base HW Sprite: 1
    ld a, SPRITE_0_PATTERN_BANK
    call mapper_set_bank_p2
    ld hl, SPRITE_0_PATTERN
    ld de, SPRPAT + (1 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    ; Entity 2: pacman_spr_right (1 layers)
    ; Base HW Sprite: 2
    ld a, SPRITE_0_PATTERN_BANK
    call mapper_set_bank_p2
    ld hl, SPRITE_0_PATTERN
    ld de, SPRPAT + (2 * 32)
    ld bc, 32 ; Load 1 layers (32 bytes each)
    call FAST_LDIRVM
    call mapper_pop_p2
    ret

; ==================================================================
; SPRITE MANAGEMENT FUNCTIONS
; ==================================================================

; A = hardware sprite index, B = X, C = Y, D = pattern, E = color
show_sprite:
    ; Safety check: Ensure sprite index < 32
    cp 32
    ret nc

    ; Safety check: Never write Y >= 208 (208 is SAT end marker on MSX)
    push af
    ld a, c
    cp 208
    jr c, .y_ok
    ld c, SPRITE_INVISIBLE
.y_ok:
    pop af

    ; Save pattern (D) and color (E) before calculating address
    push de

    ; Calculate base address for sprite: index * 4
    ld l, a
    ld h, 0
    add hl, hl      ; index * 2
    add hl, hl      ; index * 4
    ; Add base of the attribute table
    ld de, sprite_attributes
    add hl, de      ; HL = &sprite_attributes[index * 4]

    ; Restore pattern and color
    pop de

    ; Write attributes
    ld (hl), c      ; Y
    inc hl
    ld (hl), b      ; X
    inc hl
    ld (hl), d      ; Pattern
    inc hl
    ld (hl), e      ; Color

    ld a, 1
    ld (sprites_dirty), a
    ret

; Clear all sprites (set Y = SPRITE_INVISIBLE)
; OPTIMIZED: Uses faster increment method instead of ADD HL,DE
clear_all_sprites:
    ld hl, sprite_attributes
    ld b, 32
    ld a, SPRITE_INVISIBLE
.sprite_clear_loop:
    ld (hl), a      ; Set Y = SPRITE_INVISIBLE
    inc hl          ; Skip to X
    inc hl          ; Skip to Pattern
    inc hl          ; Skip to Color
    inc hl          ; Next sprite (4× INC HL = 24 cycles vs ADD HL,DE = 35 cycles)
    djnz .sprite_clear_loop
    ld a, 1
    ld (sprites_dirty), a
    ret

; Hide specific sprite (A = hardware sprite index)
hide_sprite:
    cp 32
    ret nc
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    ld de, sprite_attributes
    add hl, de
    ld (hl), SPRITE_INVISIBLE
    ld a, 1
    ld (sprites_dirty), a
    ret

; Copy sprite attributes from RAM to VRAM
update_sprites_to_vram:
    ld a, (sprites_dirty)
    or a
    ret z
    xor a
    ld (sprites_dirty), a
    ld hl, sprite_attributes
    ld de, SPRATR
    ld bc, 128  ; 4 bytes per sprite
    call FAST_LDIRVM
    ret

; ==================================================================
; SPRITE CONSTANTS
; ==================================================================
SPRITE_INVISIBLE    EQU 224

