load_screen_game_zone_756558729940:
    ; Load game_zone screen (fast direct port access)
    ; Active Area: X=0, Y=0, W=26, H=24
    ; Preserve HUD/non-active area: only overwrite active game area
    ; Set VDP colors FIRST (before loading screen data)
    ld a, 1           ; Background color
    ld b, 1       ; Border color
    call set_screen_colors
    ; Initialize character 0 (empty cells) with background color
    ld a, 1           ; Background color for char 0
    call init_char0_color
    ; Clear hardware sprites on screen switch to avoid visual carry-over
    call clear_all_sprites
    call update_sprites_to_vram
    ; Load active game area (rectangular copy by rows)
    call mapper_push_p2
    ld a, SCREEN_GAME_ZONE_0_LAYOUT_BANK
    call mapper_set_bank_p2
    ld hl, SCREEN_GAME_ZONE_0_LAYOUT + 0
    ld de, NAMETBL + 0
    ld a, 24
    ld c, 26
    call copy_layout_rect_to_vram
    call mapper_pop_p2
    ; Build mutable runtime screen/behavior maps in RAM
    call mapper_push_p2
    ld a, SCREEN_GAME_ZONE_0_LAYOUT_BANK
    call mapper_set_bank_p2
    ld hl, SCREEN_GAME_ZONE_0_LAYOUT
    ld de, runtime_screen_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    call mapper_pop_p2

    call mapper_push_p2
    ld a, BEHAVIOR_GAME_ZONE_0_DATA_BANK
    call mapper_set_bank_p2
    ld hl, BEHAVIOR_GAME_ZONE_0_DATA
    ld de, runtime_behavior_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    call mapper_pop_p2
    ; Initialize collision system pointers for this screen
    ld hl, runtime_screen_layout
    ld (current_screen_layout), hl
    ld a, #FF
    ld (current_screen_layout_bank), a
    ld hl, runtime_behavior_map
    ld (current_behavior_map), hl
    ld a, #FF
    ld (current_behavior_map_bank), a
    ld a, l
    ld (behavior_cache_map_l), a
    ld a, h
    ld (behavior_cache_map_h), a
    ld a, #FF
    ld (behavior_cache_row), a
    ret

