    DB 1, 224, 40    ; Element 2: Score at (224,40)
    DB 2, 1, 0 ; W, H, Flags
    DW hud_text_2             ; Text pointer
    DB 1                ; Visible
    DB 8, 216, 56    ; Element 3: CoinCounter at (216,56)
    DB 4, 1, 0 ; W, H, Flags
    DW hud_text_3             ; Text pointer
    DB 1                ; Visible
    DB 2, 224, 72    ; Element 4: HighScore at (224,72)
    DB 2, 1, 0 ; W, H, Flags
    DW hud_text_4             ; Text pointer
    DB 1                ; Visible
    DB 2, 216, 88    ; Element 5: HighScore at (216,88)
    DB 4, 1, 0 ; W, H, Flags
    DW hud_text_5             ; Text pointer
    DB 1                ; Visible
    DB 12, 216, 8    ; Element 6: TextBox at (216,8)
    DB 4, 1, 1 ; W, H, Flags
    DW hud_text_6             ; Text pointer
    DB 1                ; Visible
    DB 8, 224, 24    ; Element 7: CoinCounter at (224,24)
    DB 2, 1, 0 ; W, H, Flags
    DW hud_text_7             ; Text pointer
    DB 1                ; Visible
    DB 1, 224, 40    ; Element 8: Score at (224,40)
    DB 2, 1, 0 ; W, H, Flags
    DW hud_text_8             ; Text pointer
    DB 1                ; Visible
    DB 8, 216, 56    ; Element 9: CoinCounter at (216,56)
    DB 4, 1, 0 ; W, H, Flags
    DW hud_text_9             ; Text pointer
    DB 1                ; Visible

; HUD Text Strings
